1	// Land a task's delivered pull request under the REPO's delivery settings — the
2	// single home for the auto-merge nuances every PR-delivering task shares. These
3	// helpers were built inside the baselining worker (#455/#565/#649/#677/#690);
4	// they live here because the other landing tasks hit the identical failure
5	// shapes (an arm rejected "clean status" on an ungated base stranding a green PR
6	// forever), and two copies of this precedence is exactly the drift the corpus
7	// forbids.
8	//
9	// The contract that keeps tasks simple: a task declares only its outcome CEILING
10	// (`automerge` — what it MAY land; merge-policy.mjs owns whether a granular
11	// policy covers the actual diff). Whether the PR actually
12	// lands unreviewed is the MEMBER REPO's call — `dailyClaudiniteUpdatesRequirePrReview`
13	// in its settings file, where `true` degrades every authorized landing to review
14	// (member config wins, docs/PRINCIPLES.md). Tasks stay
15	// unaware of that setting by construction: they hand their PR to landDelivery()
16	// (directly, or through deliver-generated.mjs) and the repo-shape nuances stay
17	// here:
18	//
19	//   - `review` member          → the PR is opened and LEFT — never armed, never merged.
20	//   - no pull_request CI at all → MERGE directly. GitHub's auto-merge is a queue
21	//     for checks; with nothing to queue behind, the arm is rejected ("Pull
22	//     request is in clean status") every time, and while that rejection was
23	//     swallowed a repo that asked for auto-merge got no merge at all.
24	//   - CI present, but the base branch REQUIRES nothing → the arm is equally
25	//     doomed (same clean-status rejection, #677): skip it, wait for this run's
26	//     own dispatched evidence, and land on it (verify-then-merge).
27	//   - a base gate present — or unreadable, which is never read as absent → ARM,
28	//     with the landing poll as fallback when the arm is rejected (auto-merge
29	//     disabled repo-side, or a pull_request run parked at `action_required`).
30	//
31	// A branch pushed and a PR opened over the Action's GITHUB_TOKEN emit no
32	// pull_request run of their own (GitHub's recursion guard, #565), so
33	// landDelivery also STARTS the PR's checks via workflow_dispatch before deciding
34	// anything — the checks an arm would wait on must exist to conclude.
35	//
36	// The AGENT lane (executor subagents, MCP writes) cannot run this module; its
37	// prose twin is `deliver-pr.md` beside this file, and the two must keep saying
38	// the same thing — a nuance changed here changes there in the same commit.
39	//
40	// DISPOSING of a previous run's pull request is NOT here: which pull request a run
41	// works on — reuse it, supersede it, land it — is the executor's single decision
42	// (`queue/target.mjs`), and `pullDisposition` below is the predicate it judges with.
43	
44	import { taskTrailer } from '../../public/work-item-grammar.mjs';
45	import { restCall, graphqlCall } from '../world/github.mjs';
46	import { nowMs } from '../world/clock.mjs';
47	
48	
49	// The squash-merge request body. THE MERGE COMMIT is what lands on the default
50	// branch, so it — not only the branch's own commits — has to say which task
51	// wrote it, or the `commits` collector reads a task's own delivery as the
52	// project moving and every task keeps its neighbours awake. `commit_message`
53	// replaces the squash body GitHub would compose; the title it leaves alone, so
54	// the merge still reads as the PR it was.
55	//
56	// A caller with no task to name (a member's own script, a hand-run worker) sends
57	// the plain merge, and the older author/title exclusions classify it as they
58	// always did.
59	const squashBody = (task) => {
60	  const trailer = taskTrailer(task);
61	  return { merge_method: 'squash', ...(trailer ? { commit_message: trailer } : {}) };
62	};
63	
64	const gh = (token, path, opts) => restCall(token, path, opts);
65	
66	// --- the member's delivery preference ----------------------------------------
67	
68	// The member's delivery preference, normalized. `push`/`auto` → auto-merge and
69	// `pr` → review are the permanent legacy aliases (the maintenance-lane tolerance);
70	// anything else is invalid (null) and fails the run rather than guessing.
71	export function normalizeDelivery(raw) {
72	  const v = String(raw ?? '').trim();
73	  if (v === 'auto-merge' || v === 'auto' || v === 'push') return 'auto-merge';
74	  if (v === 'review' || v === 'pr') return 'review';
75	  return null;
76	}
77	
78	// The default a repo gets when it never declared one.
79	export const DEFAULT_DELIVERY = 'auto-merge';
80	
81	// @deprecated — the `maintenance.delivery` resolution, kept callable for the
82	// fielded workers that still import it (an `updates/*`-class surface: a member's
83	// vendored worker is a cycle behind the flows that rewrote its declaration). New
84	// callers ask `deliveryFor` below, which reads the current key.
85	//
86	// `maintenance.delivery` was always EXPLICIT — but a key that is simply absent is
87	// DRIFT, not an error. A repo adopted before the key existed, or one whose key
88	// was hand-removed, would otherwise fail its scheduled tasks every night forever
89	// with nothing that could ever fix it. So: resolve to the default and carry on —
90	// `materialize: true` tells the one caller that CAN write the repair to do so.
91	//
92	// An UNRECOGNIZED value is a different thing entirely: someone wrote an intent
93	// this code cannot honour, and silently substituting a default would deliver
94	// the opposite of what they asked for. That still fails the run (delivery: null).
95	export function resolveDelivery(raw) {
96	  if (raw == null || String(raw).trim() === '') {
97	    return { delivery: DEFAULT_DELIVERY, materialize: true };
98	  }
99	  return { delivery: normalizeDelivery(raw), materialize: false };
100	}
101	
102	// @deprecated with `resolveDelivery` above, and kept callable for the same reason.
103	export function deliveryFromChecks(text) {
104	  let parsed = null;
105	  try { parsed = JSON.parse(text ?? 'null'); } catch { /* unreadable → absent */ }
106	  return resolveDelivery(parsed?.maintenance?.delivery);
107	}
108	
109	// THE MEMBER'S DELIVERY, from its parsed settings. One override, one direction:
110	// `dailyClaudiniteUpdatesRequirePrReview: true` leaves the PR for a human, and
111	// anything else — the key absent, which is the normal shape — lands it. That
112	// asymmetry is the point of #1252: every member wanted the same thing, so the
113	// setting materialized into every declaration said nothing, and the one repo that
114	// wants review is the one that should have to say so.
115	//
116	// The retired `maintenance.delivery` is read underneath for a member the rename
117	// record has not reached. Unparsable or absent settings resolve like an absent
118	// key — auto-merge, not failure: the file's integrity is check_the_world's
119	// problem, not the delivery step's.
120	export function deliveryFor(settings) {
121	  if (settings?.dailyClaudiniteUpdatesRequirePrReview === true) return 'review';
122	  if (settings?.dailyClaudiniteUpdatesRequirePrReview === undefined
123	      && normalizeDelivery(settings?.maintenance?.delivery) === 'review') return 'review';
124	  return DEFAULT_DELIVERY;
125	}
126	
127	// The same, from the raw TEXT of a settings file — the shape a caller reading the
128	// file off a git blob has in hand.
129	export function deliveryForText(text) {
130	  let parsed = null;
131	  try { parsed = JSON.parse(text ?? 'null'); } catch { /* unreadable → absent */ }
132	  return deliveryFor(parsed);
133	}
134	
135	// --- CI dispatch on the delivered PR (#565) -----------------------------------
136	// The GITHUB_TOKEN push/PR-open emits no pull_request run (GitHub's recursion
137	// guard), so the delivery starts the PR's checks itself: dispatch every workflow
138	// that WOULD have run on pull_request and CAN be dispatched.
139	//
140	// "Suppresses" is only half true, and the other half is #455/#205/#95: on some
141	// members GitHub CREATES the pull_request run and parks it at `action_required`
142	// awaiting an approval nobody clicks. The dispatch above still supplies the real
143	// green, but the parked run is what auto-merge refuses over — which is why
144	// arming is not the end of the story and pullDisposition exists.
145	//
146	// Reading the triggers is a best-effort TEXTUAL scan of a workflow's top-level
147	// `on:` block (no YAML parser in the corpus). It covers the shapes workflows
148	// actually use: a block map of trigger keys (with or without nested config), the
149	// inline scalar, and the inline list.
150	export function workflowTriggers(yaml) {
151	  const lines = String(yaml ?? '').split('\n');
152	  const onAt = lines.findIndex((l) => /^(['"]?)on\1\s*:/.test(l));
153	  if (onAt === -1) return [];
154	  const inline = lines[onAt].replace(/^(['"]?)on\1\s*:/, '').replace(/#.*$/, '').trim();
155	  if (inline) return inline.replace(/[[\]]/g, '').split(',').map((s) => s.trim()).filter(Boolean);
156	  const triggers = [];
157	  let childIndent = null;
158	  for (let i = onAt + 1; i < lines.length; i += 1) {
159	    const line = lines[i];
160	    if (!line.trim() || line.trim().startsWith('#')) continue;
161	    const indent = line.length - line.trimStart().length;
162	    if (indent === 0) break;                        // next top-level key — on: is done
163	    childIndent = childIndent ?? indent;            // first child fixes the trigger level
164	    if (indent !== childIndent) continue;           // nested config under a trigger
165	    const m = /^([A-Za-z_]+)\s*:/.exec(line.trim());
166	    if (m) triggers.push(m[1]);
167	  }
168	  return triggers;
169	}
170	
171	// The dispatch plan over the repo's workflow files ({name, content} each):
172	// `dispatch` — runs on pull_request AND carries workflow_dispatch (start these);
173	// `missing`  — runs on pull_request but CANNOT be dispatched (name these in the
174	// log: adding `workflow_dispatch:` to that file's `on:` is the owner's one-line
175	// fix, and silence here would read as "no CI expected" when CI was expected).
176	// A workflow with no pull_request trigger is never touched — dispatchable-but-
177	// unrelated workflows (a release orchestrator, say) must not fire on a delivery.
178	export function ciDispatchPlan(files) {
179	  const dispatch = [];
180	  const missing = [];
181	  for (const { name, content } of files ?? []) {
182	    const triggers = workflowTriggers(content);
183	    if (!triggers.includes('pull_request')) continue;
184	    (triggers.includes('workflow_dispatch') ? dispatch : missing).push(name);
185	  }
186	  return { dispatch, missing };
187	}
188	
189	// The I/O half of the CI dispatch: read the workflow files as they exist ON THE
190	// DELIVERED BRANCH (the delivery may itself have changed them), plan with
191	// ciDispatchPlan, POST a dispatch per selected workflow, and log every outcome —
192	// a silent no-checks PR is exactly the failure mode this exists to close. Needs
193	// the scheduler workflow's `actions: write` (a read-only token 403s the POST
194	// silently — the store-release lesson).
195	// Returns { dispatch, missing, started }: `dispatch`/`missing` are the PLAN
196	// (what the tree says should run), `started` the dispatches GitHub actually
197	// accepted (204). The landing poll must wait only on `started` — a POST that
198	// 403'd (the scheduler workflow missing `actions: write`, the canon's own copy
199	// on 2026-08-08) starts nothing, and counting the plan had the poll waiting for
200	// a run that could never come.
201	export async function dispatchCiRuns({ token, repo, branch, log = console.log }) {
202	  const ref = encodeURIComponent(branch);
203	  const { json: dir } = await gh(token, `/repos/${repo}/contents/.github/workflows?ref=${ref}`);
204	  const files = [];
205	  for (const entry of Array.isArray(dir) ? dir : []) {
206	    if (!/\.ya?ml$/.test(entry.name ?? '')) continue;
207	    const { json } = await gh(token, `/repos/${repo}/contents/.github/workflows/${entry.name}?ref=${ref}`);
208	    files.push({ name: entry.name, content: json?.content ? Buffer.from(json.content, 'base64').toString('utf8') : '' });
209	  }
210	  const { dispatch, missing } = ciDispatchPlan(files);
211	  for (const name of missing) {
212	    log(`${name} runs on pull_request but has no workflow_dispatch trigger — `
213	      + 'cannot start it on the delivered PR; add `workflow_dispatch:` under its `on:` to let the delivery run it');
214	  }
215	  if (!dispatch.length && !missing.length) {
216	    log('no pull_request-triggered workflow — the delivered PR has no checks to wait for');
217	  }
218	  const started = [];
219	  for (const name of dispatch) {
220	    const res = await gh(token, `/repos/${repo}/actions/workflows/${name}/dispatches`, {
221	      method: 'POST', body: { ref: branch },
222	    });
223	    if (res.status === 204) { started.push(name); log(`dispatched ${name} on ${branch} — the delivered PR gets its checks`); }
224	    else {
225	      log(`could not dispatch ${name} on ${branch} (${res.status})`
226	        + (res.status === 403 ? ' — the scheduler workflow needs `actions: write` (a read token 403s this POST silently)' : ''));
227	    }
228	  }
229	  return { dispatch, missing, started };
230	}
231	
232	// --- opening the PR ------------------------------------------------------------
233	
234	// Why the PR-open POST must be status-checked, as a pure predicate: null when
235	// the PR was created, else the message to fail on.
236	//
237	// This is the one call whose silent failure is invisible AND self-perpetuating:
238	// a cycle that pushes its branch but fails to open the PR leaves nothing for the
239	// next cycle to find, branches pile up nightly, and the run still reports `ok`
240	// because nothing read the status. The usual cause is repo-level and invisible
241	// from here — "Allow GitHub Actions to create and approve pull requests" is off
242	// and the POST 403s — so the message names that remedy rather than leaving a
243	// bare status code.
244	export function pullCreateError(status, json) {
245	  if (status === 201 && json?.number) return null;
246	  const detail = json?.message ?? `HTTP ${status}`;
247	  return `${detail} — if this is the Actions PR permission, enable Settings → Actions`
248	    + ' → General → "Allow GitHub Actions to create and approve pull requests"';
249	}
250	
251	// --- the delivery decision -------------------------------------------------------
252	
253	// How an `auto-merge` member's PR actually lands, given whether this repo has any
254	// pull_request-triggered workflow at all.
255	//
256	// GitHub's auto-merge is a QUEUE FOR CHECKS. On a repo with no PR CI there is
257	// nothing to queue behind: the mutation is rejected ("Pull request is in clean
258	// status"), and since the failure was swallowed the PR sat open forever — a repo
259	// that asked for `auto-merge` got no merge at all. Seven of twelve consumers were
260	// in exactly that shape (no `pull_request` trigger anywhere in .github/workflows).
261	//
262	// So: no CI to wait for → MERGE IT, which is what `auto-merge` meant all along.
263	//
264	// `hasPrCi` comes from ciDispatchPlan over the branch's own workflow files —
265	// `dispatch` (startable) plus `missing` (PR-triggered but not dispatchable). Both
266	// empty means no workflow anywhere runs on a pull_request, so no check will ever
267	// appear. That is a fact about the tree, not a race against checks registering.
268	//
269	// `gate` is what the BASE BRANCH requires (classifyMergeGate) — the thing
270	// GitHub's auto-merge actually queues behind. CI existing was the wrong
271	// predicate (#677): on an unprotected base the PR is mergeable the whole time
272	// its checks run, so `enablePullRequestAutoMerge` is rejected "clean status"
273	// every cycle no matter how green — arming there is doomed, and the delivery
274	// goes straight to verify-then-land instead. `unknown` arms: a gate we could
275	// not see is never merged past.
276	export function deliveryAction({ delivery, hasPrCi, gate = 'unknown' }) {
277	  if (delivery !== 'auto-merge') return 'none';
278	  if (!hasPrCi) return 'merge';
279	  return gate === 'absent' ? 'land' : 'arm';
280	}
281	
282	// What the base branch requires before a merge, from the two reads the Action's
283	// GITHUB_TOKEN can make: the branch's `protected` flag and the ruleset rules
284	// that apply to it (deliberately NOT /branches/{base}/protection, which wants
285	// admin). Rule types that queue a PR gate it; rules about pushes and deletions
286	// do not. An unreadable answer is UNKNOWN, never absent — unknown assumes a
287	// gate, so the caller arms rather than merging past a gate it cannot see.
288	const GATING_RULE_TYPES = ['pull_request', 'required_status_checks', 'merge_queue', 'required_deployments'];
289	export function classifyMergeGate({ branchStatus, branchJson, rulesStatus, rulesJson }) {
290	  if (branchStatus !== 200 || typeof branchJson?.protected !== 'boolean') return 'unknown';
291	  if (branchJson.protected) return 'present';
292	  if (rulesStatus !== 200 || !Array.isArray(rulesJson)) return 'unknown';
293	  return rulesJson.some((r) => GATING_RULE_TYPES.includes(r?.type)) ? 'present' : 'absent';
294	}
295	
296	export async function readMergeGate(token, repo, base) {
297	  const branch = await gh(token, `/repos/${repo}/branches/${encodeURIComponent(base)}`);
298	  const rules = await gh(token, `/repos/${repo}/rules/branches/${encodeURIComponent(base)}`);
299	  return classifyMergeGate({
300	    branchStatus: branch.status, branchJson: branch.json,
301	    rulesStatus: rules.status, rulesJson: rules.json,
302	  });
303	}
304	
305	// --- judging a PR by the runs on its head (#455/#205/#95) ---------------------
306	// Arming is best-effort and can fail PERMANENTLY, so "arm and move on" is not a
307	// delivery guarantee. Two shapes, both observed across the fleet, both leaving a
308	// green PR open forever:
309	//
310	//   1. GATED CI. GitHub CREATES the pull_request run for a GITHUB_TOKEN push and
311	//      parks it at conclusion `action_required`, pending a human "Approve and
312	//      run" that nobody is watching for. The run never executes, so it never
313	//      reports; `enablePullRequestAutoMerge` then refuses the PR with "in
314	//      unstable status (required checks are failing)". Meanwhile the
315	//      workflow_dispatch run started on the SAME head sha ran and passed. So CI
316	//      did pass; only the phantom gated run says otherwise.
317	//   2. AUTO-MERGE OFF. The repo never enabled Settings → General → "Allow
318	//      auto-merge", so the mutation is rejected outright no matter how green.
319	//
320	// Both are settled by the same evidence: the runs on the PR's own head sha. If
321	// CI has CONCLUDED and nothing actually failed, the content on that sha is
322	// verified and `auto-merge` means merge it. A gated `action_required` run is not
323	// a failure — it is a run that never happened.
324	//
325	// Deliberately conservative about MERGING, because that bypasses the arm:
326	//   - Anything still queued/running → `wait`. Never merge mid-flight.
327	//   - Any real failure (failure / timed_out / cancelled / startup_failure), or no
328	//     successful run to stand on → `close`: NOT a merge, and equally not a reuse.
329	//     (What `close` means is the CALLER's policy — a supersede resolution takes a
330	//     fresh branch and closes the previous delivery; a landing pass just leaves the
331	//     PR standing.)
332	//
333	// A `review` member's PR is the owner's to act on, on their own clock — never
334	// merged, and never closed out from under them either.
335	export const REAL_FAILURES = ['failure', 'timed_out', 'cancelled', 'startup_failure'];
336	
337	export function pullDisposition({ delivery, runs }) {
338	  if (delivery !== 'auto-merge') return 'keep';
339	  const list = (runs ?? []).filter(Boolean);
340	  if (list.some((r) => r.status !== 'completed')) return 'wait';
341	  if (list.some((r) => REAL_FAILURES.includes(r.conclusion))) return 'close';
342	  if (!list.some((r) => r.conclusion === 'success')) return 'close';
343	  return 'merge';
344	}
345	
346	// Why the merge had to happen here rather than through the arm. The log line has
347	// to name which shape this was, or the repo misconfiguration behind it stays
348	// invisible — and it is a REPO setting, so only a human can retire it.
349	export function mergeReason(runs) {
350	  // The no-remedy shape names no setting (#677): on a base that requires
351	  // nothing, landing here IS the design, and sending an owner to fix something
352	  // already correct is worse than saying nothing.
353	  return (runs ?? []).some((r) => r?.conclusion === 'action_required')
354	    ? 'its pull_request run is parked at action_required (never ran) while the dispatched run passed'
355	    + ' — check Settings → Actions → General → workflow-approval requirements'
356	    : 'its dispatched checks concluded green and nothing on the base branch queues an auto-merge';
357	}
358	
359	// Why a PR was left (or closed) rather than merged — the same visibility
360	// argument, for the case that matters more: a member whose CI is genuinely red.
361	export function failureSummary(runs) {
362	  const list = (runs ?? []).filter(Boolean);
363	  const failed = list.filter((r) => REAL_FAILURES.includes(r?.conclusion));
364	  if (failed.length) return `failing CI: ${failed.map((r) => `${r.name} ${r.conclusion}`).join(', ')}`;
365	  // A run still going at the bound is a statement about the CLOCK, not a verdict
366	  // on the runs, and conflating the two sent a reader to a repository-settings
367	  // diagnosis for a repo where nothing was misconfigured (#1026). Name what is
368	  // still moving, so a member whose CI outruns the budget is visible as itself.
369	  const inFlight = list.filter((r) => r?.status && r.status !== 'completed');
370	  if (inFlight.length) {
371	    return 'still running at the landing bound: '
372	      + `${inFlight.map((r) => `${r.name} ${r.status}`).join(', ')} — it lands next cycle`;
373	  }
374	  return 'no successful run on its head sha';
375	}
376	
377	// --- landing THIS run's PR when the arm could not (#649) ----------------------
378	// On a member whose pull_request run is gated, EVERY arm fails; deferring to the
379	// next cycle's disposal put a standing ~24h offset between a task's output and
380	// that member's main. The evidence that settles it does not take a day to
381	// arrive: the dispatched run this delivery just started concludes in minutes at
382	// worst. So we wait for it, once, and merge on exactly the reasoning disposal
383	// uses. Same decision, made now.
384	//
385	// Bounded and cheap because it only runs where the arm ALREADY failed (or was
386	// skipped as doomed): a healthy member arms and returns without waiting at all.
387	//
388	// TWO BOUNDS, because the poll waits on two different things and one number
389	// answered both wrongly (#1026). Nothing VISIBLE is the short case: a dispatch
390	// that has registered no run is a dispatch that may never register one, so
391	// waiting long buys nothing. A run we can see EXECUTING is the opposite — the
392	// evidence is on its way and the only question is whether the prework budget
393	// outlasts it. Collapsed into one 180s bound, a member whose slowest check took
394	// 3m29s had its green PR abandoned 26s short every cycle and landed a day late
395	// by the next cycle's disposal, which is exactly the offset #649 closed.
396	//
397	// The in-flight bound is ceilinged by the PREWORK budget it spends, not by what
398	// CI might take: the shortest `prework_timeout` among the tasks that land their
399	// own PR is 600s, and the poll is the tail of a prework that has already
400	// converged a tree and opened a PR. 300s leaves that preamble its room. A member
401	// whose CI outruns even this still lands next cycle — but now it SAYS so
402	// (failureSummary below), where before the give-up was indistinguishable from a
403	// red repo.
404	export const LAND_TIMEOUT_MS = 180_000;
405	export const LAND_INFLIGHT_TIMEOUT_MS = 300_000;
406	export const LAND_POLL_MS = 5_000;
407	
408	// What one poll of the head sha's runs says to do: `merge`, `poll` again, or
409	// `give-up` and leave the PR standing.
410	//
411	// It NEVER closes. A cycle's disposal may close a PR because that PR is LAST
412	// cycle's and this cycle is about to re-cut it; here the PR IS this run's
413	// delivery, and closing it would throw away the work that just ran. A red member
414	// therefore leaves its PR open for the next run (or a human) to dispose of.
415	// `expected` is how many verification runs THIS delivery dispatched on the head
416	// seconds ago. Fewer visible runs than that is the API still registering them —
417	// a POLL, never a verdict. Without it, the first read 0.3s after the dispatch
418	// found an empty list and judged "nothing will ever verify this", stranding
419	// seven members' green PRs in one forced fleet pass (2026-08-07).
420	export function landAttempt({
421	  delivery, runs, expected = 0, elapsedMs = 0,
422	  timeoutMs = LAND_TIMEOUT_MS, inflightTimeoutMs = LAND_INFLIGHT_TIMEOUT_MS,
423	}) {
424	  if ((runs ?? []).length < expected) return elapsedMs >= timeoutMs ? 'give-up' : 'poll';
425	  const disposition = pullDisposition({ delivery, runs });
426	  if (disposition === 'merge') return 'merge';
427	  // `wait` is precisely "a run is not `completed`" — the seen-it-executing case,
428	  // which gets the longer budget.
429	  if (disposition === 'wait') return elapsedMs >= inflightTimeoutMs ? 'give-up' : 'poll';
430	  return 'give-up';
431	}
432	
433	// Arm native auto-merge on a PR (by node id) via the GraphQL mutation — the REST
434	// `PUT /merge` would merge NOW, ignoring pending checks; this waits for them.
435	export async function enableAutoMerge(token, pullRequestId) {
436	  const query = 'mutation($id:ID!){enablePullRequestAutoMerge(input:{pullRequestId:$id,mergeMethod:SQUASH}){pullRequest{id}}}';
437	  const json = await graphqlCall(token, query, { id: pullRequestId });
438	  if (json?.errors?.length) throw new Error(json.errors[0].message);
439	}
440	
441	// Tidy the ref behind a merged (or disposed) PR — a dead branch left on the
442	// remote is litter that accumulates one per run. Never fatal: the branch is not
443	// the deliverable.
444	export async function deleteBranch({ token, repo, ref, log = console.log }) {
445	  if (!ref) return;
446	  const res = await gh(token, `/repos/${repo}/git/refs/heads/${encodeURIComponent(ref)}`, { method: 'DELETE' });
447	  if (res.status !== 204) log(`could not delete branch ${ref} (HTTP ${res.status})`);
448	}
449	
450	const sleep = (ms) => new Promise((resolve) => { setTimeout(resolve, ms); });
451	
452	// The I/O half of same-run landing: poll this PR's head sha until its runs have
453	// concluded, then merge on the same evidence disposal would use a cycle later.
454	// Returns true iff it merged. Best-effort throughout — every failure path leaves
455	// the PR exactly as the arm left it, which is what the next run expects.
456	export async function landNow({ token, repo, pr, delivery, expected = 0, task = null, log = console.log }) {
457	  const started = nowMs();
458	  for (;;) {
459	    const { status, json } = await gh(token, `/repos/${repo}/actions/runs?head_sha=${pr.head?.sha ?? ''}&per_page=100`);
460	    if (status !== 200) {
461	      log(`could not read this run's checks for PR #${pr.number} (HTTP ${status}) — leaving it for the next run`);
462	      return false;
463	    }
464	    const runs = (json?.workflow_runs ?? []).map((r) => ({ name: r.name, status: r.status, conclusion: r.conclusion }));
465	    const attempt = landAttempt({ delivery, runs, expected, elapsedMs: nowMs() - started });
466	
467	    if (attempt === 'poll') { await sleep(LAND_POLL_MS); continue; }
468	    if (attempt === 'give-up') {
469	      log(`PR #${pr.number} not landable this run (${failureSummary(runs)})`
470	        + ' — leaving it open for the next run to dispose of');
471	      return false;
472	    }
473	
474	    const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
475	      method: 'PUT', body: squashBody(task),
476	    });
477	    if (res.status === 200) {
478	      log(`merged PR #${pr.number} in-cycle — ${mergeReason(runs)}`);
479	      await deleteBranch({ token, repo, ref: pr.head?.ref, log });
480	      return true;
481	    }
482	    log(`could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`
483	      + ' — leaving it for the next run');
484	    return false;
485	  }
486	}
487	
488	// The whole landing, composed — what a task's delivery calls once its PR exists.
489	// Dispatch the PR's checks (they establish `hasPrCi`, the fact deliveryAction
490	// turns on), read what the base requires, then merge / land / arm per the
491	// decision — with the landing poll as fallback for a failed arm. `pr` must carry
492	// the CURRENT head ({ number, node_id, head: { ref, sha } }): after a force-push,
493	// a stale sha polls runs that will never conclude.
494	//
495	// Returns { merged, action }. `action: 'none'` is the review member — the PR
496	// stands, deliberately, and that is a delivered outcome, not a failure.
497	export async function landDelivery({ token, repo, base, pr, delivery, task = null, log = console.log }) {
498	  // Start the PR's checks FIRST — the GITHUB_TOKEN push/open emitted no
499	  // pull_request event, so without this the PR has no runs (#565). AFTER the
500	  // push, so the dispatched runs execute the branch's own head. Best-effort: a
501	  // dispatch failure must not fail the delivery that was already pushed. Run for
502	  // review members too — their owner wants green checks to review against.
503	  const ci = await dispatchCiRuns({ token, repo, branch: pr.head?.ref, log })
504	    .catch((e) => { log(`CI dispatch on ${pr.head?.ref} failed: ${e.message}`); return null; });
505	  const hasPrCi = ci ? ci.dispatch.length + ci.missing.length > 0 : true; // unknown → assume CI, never merge blind
506	  // How many verification runs this delivery ACTUALLY started on the head — what
507	  // the landing poll waits to see registered before it judges anything
508	  // (landAttempt). `started`, never the plan: a rejected dispatch POST starts
509	  // nothing, and waiting on the plan wedges the poll against a run that can
510	  // never come.
511	  const expected = ci?.started?.length ?? 0;
512	
513	  const gate = await readMergeGate(token, repo, base).catch(() => 'unknown');
514	  const action = deliveryAction({ delivery, hasPrCi, gate });
515	  let merged = false;
516	
517	  if (action === 'merge') {
518	    const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
519	      method: 'PUT', body: squashBody(task),
520	    });
521	    if (res.status === 200) { merged = true; log(`merged PR #${pr.number} directly — this repo has no pull_request CI to gate on`); }
522	    else log(`could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`);
523	  } else if (action === 'land') {
524	    // The base requires nothing, so auto-merge has no queue to wait behind and
525	    // the arm mutation would be rejected "clean status" — every run, no setting
526	    // to fix (#677). Skip the doomed arm; wait for this run's own dispatched
527	    // evidence and land on it. Delivery must land every cycle, not heal next cycle.
528	    log(`${base} requires nothing to merge — skipping the doomed auto-merge arm;`
529	      + ` waiting for this run's ${expected} dispatched run(s) and landing PR #${pr.number} here`);
530	    merged = await landNow({ token, repo, pr, delivery, expected, task, log });
531	  } else if (action === 'arm' && pr.node_id) {
532	    // Surfaced, not swallowed: a failed arm is why a delivered PR sits open
533	    // forever, and the two usual causes are both fixable repo settings.
534	    const armed = await enableAutoMerge(token, pr.node_id).then(() => true)
535	      .catch((e) => {
536	        log(`could not arm auto-merge on PR #${pr.number}: ${e.message}`
537	          + ' — check Settings → General → "Allow auto-merge", and Settings → Actions → General for a'
538	          + ' workflow-approval requirement parking this PR\'s pull_request run at action_required.'
539	          + ' Waiting for this run\'s dispatched checks and landing it here.');
540	        return false;
541	      });
542	    // Only where the arm failed. A member that armed is GitHub's to land, and
543	    // waiting on it here would add a poll to every healthy repo for nothing.
544	    if (!armed) merged = await landNow({ token, repo, pr, delivery, expected, task, log });
545	  }
546	  return { merged, action };
547	}
548

